// Des: CLI: show a host's effective settings, check site rules
// Flo: site --check > validate groups, sites, paths > site <host or url> > merge layers > one line per changed key with its source
// I/O: Ctx (caller) > text or JSON lines; exit 0 ok, 2 bad usage, config error otherwise
// ===================================================================
const std = @import("std"); const ctxm = @import("ct-ctrl-ctxz.zig"); const site = @import("cf-site-rule.zig"); const urln = @import("ut-urlz-norm.zig");
const Line = struct { keyz: []const u8, valu: []const u8, from: []const u8 };
const Repo = struct { host: []const u8, path: []const u8, rule: []const u8, list: []const Line };
fn itemSize(valu: ?std.json.Value) usize { const valz = valu orelse return 0; return switch (valz) { .array => |list| list.items.len, .object => |objz| objz.count(), else => 0 }; }
pub fn siteShow(ctxz: *const ctxm.Ctxz) !u8 { if (ctxz.args.chek) { var diag: site.Diag = .{}; site.siteChek(ctxz.conf, &diag) catch { try ctxm.outz(ctxz, try std.fmt.allocPrint(ctxz.allo, "site rules INVALID: {s}", .{diag.text})); return error.BadConfig; }; try ctxm.outz(ctxz, try std.fmt.allocPrint(ctxz.allo, "site rules ok: {d} group(s), {d} site(s)", .{ itemSize(ctxz.conf.grup_rule_mapz), itemSize(ctxz.conf.site_rule_list) })); return 0; } if (ctxz.args.urlz.len == 0) return error.BadUsage; var host: []const u8 = ctxz.args.urlz; var path: []const u8 = "/"; if (std.mem.find(u8, ctxz.args.urlz, "://") != null) { const part = urln.urlzSpli(ctxz.args.urlz) catch return error.BadUsage; host = part.host; path = part.path; } var srcs: std.ArrayList(site.Srcz) = .empty; const outp = try site.siteExpl(ctxz.allo, ctxz.conf, host, path, &srcs); var list: std.ArrayList(Line) = .empty; var rule: []const u8 = "none (global settings only)"; for (srcs.items) |item| { var seen = false; for (list.items) |prev| { if (std.mem.eql(u8, prev.keyz, item.keyz)) seen = true; } if (seen) continue; var last = item.from; for (srcs.items) |next| { if (std.mem.eql(u8, next.keyz, item.keyz)) last = next.from; } try list.append(ctxz.allo, .{ .keyz = item.keyz, .valu = try site.valuText(ctxz.allo, outp, item.keyz), .from = last }); if (std.mem.startsWith(u8, item.from, "site ")) rule = item.from; } const repo: Repo = .{ .host = host, .path = path, .rule = rule, .list = list.items }; var text: std.ArrayList(u8) = .empty; try text.print(ctxz.allo, "host {s} path {s} | rule: {s}\n", .{ host, path, rule }); for (list.items) |line| try text.print(ctxz.allo, "  {s} = {s}   ({s})\n", .{ line.keyz, line.valu, line.from }); try ctxm.outz(ctxz, try ctxm.jsonOrzz(ctxz, repo, std.mem.trimEnd(u8, text.items, "\n"))); return 0; }
